void read_huffman_dictionary(std::ifstream &infile, std::shared_ptr<Node> &root) {
    // Read the Huffman dictionary from the binary file
    std::string symbol;
    int code;
    while (infile >> symbol >> code) {
        // Reconstruct the tree by following code paths
        std::shared_ptr<Node> current = root;
        for (char c : symbol) {
            if (c == '0') {
                if (!current->left) {
                    current->left = std::make_shared<Node>();
                }
                current = current->left;
            } else {
                if (!current->right) {
                    current->right = std::make_shared<Node>();
                }
                current = current->right;
            }
        }
        current->code = code;
        current->symbol = symbol;
    }
}
